                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "id",
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        },
        "quellenbilanz": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "type": [
              "object",
              "null"
            ],
            "properties": {
              "auId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "disposition": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "claimIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": [
                    "string",
                    "null"
                  ]
                },
                "default": null
              }
            },
            "required": [
              "auId",
              "disposition"
            ]
          },
          "default": null
        }
      },
      "required": [
        "statements"
      ]
    }
  },
  {
    "type": "function",
    "name": "submit_result",
    "description": "GENAU EINMAL am Ende: reicht Endergebnis \u002B vollstaendige Quellenbilanz ein. Validierung ist HART (Fehlerliste zurueck = nachbessern und erneut einreichen). Erst eine GUELTIGE Einreichung beendet die Aufgabe.",
    "parameters": {
      "type": "object",
      "properties": {
        "statements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              },
              "type": {
                "type": "string"
              },
              "sourceUnitIds": {
                "type": [
