                ],
                "items": {
                  "type": "string"
                }
              },
              "derivation": {
                "type": "string"
              },
              "uncertainty": {
                "type": "string"
              }
            },
            "required": [
              "id",
              "statement",
              "type",
              "sourceUnitIds",
              "derivation",
              "uncertainty"
            ]
          }
        },
        "quellenbilanz": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "auId": {
                "type": "string"
              },
              "disposition": {
                "type": "string"
              },
              "claimIds": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                },
                "default": null
              }
            },
            "required": [
              "auId",
              "disposition"
            ]
          }
