              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-005",
              "statement": "No-Gos bleiben bewohnerbezogen und gelten nicht global für alle Bewohner.",
              "type": "decision",
              "sourceUnitIds": [
                "AU-0009"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-006",
              "statement": "Beim Anlegen von No-Gos soll eine Vorlagen-Liste mit häufigen No-Gos zur Auswahl angeboten werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0009"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-007",
              "statement": "Ein Eintrag aus der Vorlagen-Liste für No-Gos darf nicht automatisch global für alle Bewohner gelten.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0009"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-008",
              "statement": "Der Sofortinfo-Bereich auf der Profil-Detailansicht soll auf maximal fünf Einträge begrenzt werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0012"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-009",
              "statement": "Beim Anlegen eines Bewohners muss mindestens ein Sofortinfo-Eintrag verpflichtend erfasst werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0012"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-010",
              "statement": "Noch nicht synchronisierte offline erfasste Inhalte müssen für den Nutzer erkennbar sein.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0014"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-011",
              "statement": "Wenn zwei Personen denselben Eintrag offline geändert haben, muss eine klare Konfliktanzeige angezeigt werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0014",
                "AU-0015"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-012",
              "statement": "Bei Offline-Konflikten darf nichts stillschweigend überschrieben werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0014"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-013",
              "statement": "Bei Offline-Konflikten soll der Nutzer entscheiden, welche Version gilt.",
              "type": "decision",
              "sourceUnitIds": [
                "AU-0015"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-014",
              "statement": "Es muss pro Schicht eine Übergabe-Notiz geben.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0016"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-015",
              "statement": "Die Übergabe-Notiz einer Schicht muss der nächsten Schicht beim Öffnen der App prominent angezeigt werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0016"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-016",
              "statement": "Übergabe-Notizen müssen mit Bewohnerprofilen verlinkbar sein.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0017"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-017",
              "statement": "Übergabe-Notizen sollen nach sieben Tagen automatisch archiviert werden.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0018"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-018",
              "statement": "Archivierte Übergabe-Notizen müssen auffindbar bleiben.",
              "type": "requirement",
              "sourceUnitIds": [
                "AU-0018"
              ],
              "derivation": "explicit",
              "uncertainty": "none"
            },
            {
              "id": "C-019",
              "statement": "Es soll eine Suche über alle Bewohnerprofile hinweg nach Stichworten geben.",
              "type": "requirement",
              "sourceUnitIds": [
